<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\OperatingUnitService;

Auth::requirePermission('catalog.manage');$tenantId=em_require_tenant();$tenantStmt=$pdo->prepare('SELECT id,name,slug,settings FROM tenants WHERE id=?');$tenantStmt->execute([$tenantId]);$tenant=$tenantStmt->fetch();if(!$tenant)exit('Empresa não encontrada.');$publicMenuUrl=app_url('menu.php?empresa='.rawurlencode((string)$tenant['slug']));$unitService=new OperatingUnitService();$currentUnit=$unitService->current();$unitId=$currentUnit?(int)$currentUnit['id']:0;

$normalizeUnit=static function(string$value,string$fallback='un'):string{$value=mb_strtolower(trim($value));$value=preg_replace('/\s+/u',' ',$value)??'';$value=mb_substr($value,0,24);return$value!==''?$value:$fallback;};
if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');
    if($action==='category-save'){$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));if($name==='')exit('Categoria inválida.');if($id){$s=$pdo->prepare('UPDATE categories SET name=?,sort_order=?,active=? WHERE id=? AND tenant_id=?');$s->execute([$name,(int)($_POST['sort_order']??0),isset($_POST['active'])?1:0,$id,$tenantId]);}else{$s=$pdo->prepare('INSERT INTO categories (tenant_id,name,sort_order,active) VALUES (?,?,?,1)');$s->execute([$tenantId,$name,(int)($_POST['sort_order']??0)]);$id=(int)$pdo->lastInsertId();}Auth::audit('category.saved','category',(string)$id);em_flash('ok','Categoria salva.');em_go('products');}
    if($action==='product-save'){
        $id=(int)($_POST['id']??0);$name=mb_substr(trim((string)($_POST['name']??'')),0,180);$sku=mb_substr(trim((string)($_POST['sku']??'')),0,80);$price=(int)round((float)str_replace(',','.',(string)($_POST['price']??'0'))*100);$cat=(int)($_POST['category_id']??0);$track=isset($_POST['track_stock'])?1:0;$description=mb_substr(trim((string)($_POST['description']??'')),0,1200);$stockUnit=$normalizeUnit((string)($_POST['stock_unit']??'un'));$purchaseUnit=$normalizeUnit((string)($_POST['purchase_unit']??$stockUnit),$stockUnit);$purchaseFactor=(float)str_replace(',','.',(string)($_POST['purchase_factor']??'1'));$minStock=(float)str_replace(',','.',(string)($_POST['min_stock_qty']??'0'));$active=isset($_POST['active'])?1:0;$imageRaw=trim((string)($_POST['image_url']??''));$image=null;
        if($name===''||$price<0||!is_finite($purchaseFactor)||$purchaseFactor<=0||!is_finite($minStock)||$minStock<0)exit('Produto inválido.');if($imageRaw!==''){$valid=filter_var($imageRaw,FILTER_VALIDATE_URL);$scheme=strtolower((string)parse_url($imageRaw,PHP_URL_SCHEME));if(!$valid||$scheme!=='https')exit('A foto precisa usar uma URL HTTPS válida. Endereços HTTP não são aceitos porque o aplicativo Android os bloqueia.');$image=mb_substr($imageRaw,0,700);}if($cat){$c=$pdo->prepare('SELECT id FROM categories WHERE id=? AND tenant_id=?');$c->execute([$cat,$tenantId]);if(!$c->fetchColumn())exit('Categoria inválida.');}
        try{Database::transaction(function(PDO$tx)use(&$id,$tenantId,$unitId,$currentUnit,$name,$sku,$price,$cat,$track,$description,$stockUnit,$purchaseUnit,$purchaseFactor,$minStock,$active,$image):void{
            if($id>0){$exists=$tx->prepare(Database::portableSql($tx,'SELECT id,track_stock FROM products WHERE id=? AND tenant_id=? FOR UPDATE'));$exists->execute([$id,$tenantId]);$current=$exists->fetch();if(!$current)throw new RuntimeException('Produto não encontrado.');if((int)$current['track_stock']===1&&$track===0){$r=$tx->prepare('SELECT COALESCE(SUM(quantity),0) FROM stock_reservations WHERE tenant_id=? AND product_id=? AND status="reserved"');$r->execute([$tenantId,$id]);if((float)$r->fetchColumn()>0)throw new RuntimeException('Não é possível desativar o estoque enquanto houver quantidade reservada em pedidos.');}$s=$tx->prepare('UPDATE products SET category_id=?,name=?,description=?,sku=?,price_cents=?,track_stock=?,image_url=?,active=?,stock_unit=?,purchase_unit=?,purchase_factor=?,min_stock_qty=? WHERE id=? AND tenant_id=?');$s->execute([$cat?:null,$name,$description,$sku?:null,$price,$track,$image,$active,$stockUnit,$purchaseUnit,$purchaseFactor,$minStock,$id,$tenantId]);if($track&&$unitId>0){$sql=Database::portableSql($tx,'INSERT IGNORE INTO unit_inventory (tenant_id,unit_id,product_id,stock_qty,average_cost_cents,min_stock_qty) VALUES (?,?,?,?,0,?)');$tx->prepare($sql)->execute([$tenantId,$unitId,$id,0,$minStock]);$tx->prepare('UPDATE unit_inventory SET min_stock_qty=?,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND unit_id=? AND product_id=?')->execute([$minStock,$tenantId,$unitId,$id]);}}
            else{$initial=(float)str_replace(',','.',(string)($_POST['stock_qty']??'0'));if(!is_finite($initial)||$initial<0)throw new RuntimeException('Estoque inicial inválido.');if($track&&$initial>0&&$unitId<1)throw new RuntimeException('Escolha a unidade no topo antes de informar estoque inicial.');$s=$tx->prepare('INSERT INTO products (tenant_id,category_id,name,description,sku,price_cents,stock_qty,track_stock,image_url,active,stock_unit,purchase_unit,purchase_factor,min_stock_qty) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$tenantId,$cat?:null,$name,$description,$sku?:null,$price,$track?$initial:0,$track,$image,$active,$stockUnit,$purchaseUnit,$purchaseFactor,$minStock]);$id=(int)$tx->lastInsertId();if($track&&$unitId>0){$tx->prepare('INSERT INTO unit_inventory (tenant_id,unit_id,product_id,stock_qty,average_cost_cents,min_stock_qty) VALUES (?,?,?,?,0,?)')->execute([$tenantId,$unitId,$id,$initial,$minStock]);if($initial>0){$key='initial-stock:'.$tenantId.':'.$unitId.':'.$id;$tx->prepare('INSERT INTO stock_movements (tenant_id,unit_id,product_id,order_id,type,quantity,idempotency_key,unit_cost_cents,total_cost_cents,reason,performed_by) VALUES (?,?,?,NULL,"in",?,?,0,0,?,?)')->execute([$tenantId,$unitId,$id,$initial,$key,'Estoque inicial do produto',Auth::id()]);}}}
            Auth::audit('product.saved','product',(string)$id,['track_stock'=>$track,'unit_id'=>$unitId?:null,'stock_unit'=>$stockUnit,'purchase_unit'=>$purchaseUnit,'purchase_factor'=>$purchaseFactor,'min_stock_qty'=>$minStock]);
        });em_flash('ok','Produto salvo e o cardápio público foi atualizado.');}catch(Throwable$e){em_flash('error',$e->getMessage());}em_go('products');
    }
}

$editId=(int)($_GET['edit']??0);$edit=null;if($editId){if($unitId>0){$s=$pdo->prepare('SELECT p.*,COALESCE(ui.stock_qty,0) unit_stock_qty,COALESCE(ui.min_stock_qty,p.min_stock_qty,0) unit_min_stock,COALESCE((SELECT SUM(sr.quantity) FROM stock_reservations sr WHERE sr.tenant_id=p.tenant_id AND sr.unit_id=? AND sr.product_id=p.id AND sr.status="reserved"),0) reserved_qty FROM products p LEFT JOIN unit_inventory ui ON ui.tenant_id=p.tenant_id AND ui.unit_id=? AND ui.product_id=p.id WHERE p.id=? AND p.tenant_id=?');$s->execute([$unitId,$unitId,$editId,$tenantId]);}else{$s=$pdo->prepare('SELECT p.*,p.stock_qty unit_stock_qty,p.min_stock_qty unit_min_stock,COALESCE((SELECT SUM(sr.quantity) FROM stock_reservations sr WHERE sr.tenant_id=p.tenant_id AND sr.product_id=p.id AND sr.status="reserved"),0) reserved_qty FROM products p WHERE p.id=? AND p.tenant_id=?');$s->execute([$editId,$tenantId]);}$edit=$s->fetch()?:null;}
$cats=$pdo->prepare('SELECT * FROM categories WHERE tenant_id=? ORDER BY sort_order,name');$cats->execute([$tenantId]);$categories=$cats->fetchAll();
if($unitId>0){$s=$pdo->prepare('SELECT p.*,c.name category_name,COALESCE(ui.stock_qty,0) unit_stock_qty,COALESCE(ui.min_stock_qty,p.min_stock_qty,0) unit_min_stock,COALESCE((SELECT SUM(sr.quantity) FROM stock_reservations sr WHERE sr.tenant_id=p.tenant_id AND sr.unit_id=? AND sr.product_id=p.id AND sr.status="reserved"),0) reserved_qty FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN unit_inventory ui ON ui.tenant_id=p.tenant_id AND ui.unit_id=? AND ui.product_id=p.id WHERE p.tenant_id=? ORDER BY p.active DESC,p.id DESC');$s->execute([$unitId,$unitId,$tenantId]);}else{$s=$pdo->prepare('SELECT p.*,c.name category_name,p.stock_qty unit_stock_qty,p.min_stock_qty unit_min_stock,COALESCE((SELECT SUM(sr.quantity) FROM stock_reservations sr WHERE sr.tenant_id=p.tenant_id AND sr.product_id=p.id AND sr.status="reserved"),0) reserved_qty FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.tenant_id=? ORDER BY p.active DESC,p.id DESC');$s->execute([$tenantId]);}$products=$s->fetchAll();$insecureImages=count(array_filter($products,static fn(array$p):bool=>str_starts_with(strtolower(trim((string)($p['image_url']??''))),'http://')));
$activeProducts=count(array_filter($products,static fn(array$p):bool=>(int)$p['active']===1));$activeCategories=count(array_filter($categories,static fn(array$c):bool=>(int)$c['active']===1));$lowStock=count(array_filter($products,static fn(array$p):bool=>(int)$p['track_stock']===1&&(float)$p['unit_stock_qty']<=(float)$p['unit_min_stock']));$averagePrice=$activeProducts?intdiv(array_sum(array_map(static fn(array$p):int=>(int)$p['price_cents'],array_filter($products,static fn(array$p):bool=>(int)$p['active']===1))),$activeProducts):0;$showEditor=$edit!==null||isset($_GET['new']);
em_header('Produtos e Estoque','products');
?>
<section class="page-hero"><div><span class="eyebrow">CATÁLOGO<?= $currentUnit?' · '.Security::e($currentUnit['name']):'' ?></span><h2>Produtos e cardápio</h2><p>Cadastro comercial é da empresa; estoque, mínimo e operação são controlados por unidade.</p></div><div class="hero-actions"><a class="button primary" href="<?= Security::e(app_url('?route=products&new=1')) ?>">+ Novo produto</a><a class="button secondary" href="<?= Security::e(app_url('?route=inventory')) ?>">Estoque</a><a class="button secondary" target="_blank" rel="noopener" href="<?= Security::e($publicMenuUrl) ?>">Ver cardápio</a></div></section>
<section class="grid dashboard-metrics"><div class="card metric"><span class="muted">Produtos publicados</span><strong><?= $activeProducts ?></strong></div><div class="card metric"><span class="muted">Categorias ativas</span><strong><?= $activeCategories ?></strong></div><div class="card metric"><span class="muted">Abaixo do mínimo<?= $currentUnit?' · '.Security::e($currentUnit['name']):'' ?></span><strong><?= $lowStock ?></strong></div><div class="card metric"><span class="muted">Preço médio</span><strong><?= em_money($averagePrice) ?></strong></div></section>
