<?php if(!$products):?><div class="alert">Você ainda não cadastrou produtos.</div><?php else:?><div class="table-wrap"><table class="table"><thead><tr><th>Produto</th><th>Categoria</th><th>Preço</th><th>Estoque<?= $currentUnit?' · '.Security::e($currentUnit['name']):'' ?></th><th>Compra</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($products as$p):$search=mb_strtolower(trim((string)$p['name'].' '.(string)($p['sku']??'')));$cat=mb_strtolower((string)($p['category_name']??'Outros'));$status=$p['active']?'published':'hidden';?><tr data-product-row data-search="<?= Security::e($search) ?>" data-category="<?= Security::e($cat) ?>" data-status="<?= $status ?>"><td><div class="product-admin-item"><?php if(!empty($p['image_url'])):?><img class="product-thumb" src="<?= Security::e($p['image_url']) ?>" alt="" loading="lazy"><?php else:?><span class="product-thumb"></span><?php endif;?><div><strong><?= Security::e($p['name']) ?></strong><?php if($p['sku']):?><br><span class="muted"><?= Security::e($p['sku']) ?></span><?php endif;?></div></div></td><td><?= Security::e($p['category_name']??'Outros') ?></td><td><strong><?= em_money($p['price_cents']) ?></strong></td><td><?php if($p['track_stock']):?><strong><?= Security::e((string)$p['unit_stock_qty'].' '.$p['stock_unit']) ?></strong><br><span class="muted">mín. <?= Security::e((string)$p['unit_min_stock']) ?> · reservado <?= Security::e((string)$p['reserved_qty']) ?></span><?php else:?><span class="muted">Sem controle</span><?php endif;?></td><td><?= Security::e($p['purchase_unit']) ?><br><span class="muted">1 = <?= Security::e((string)$p['purchase_factor'].' '.$p['stock_unit']) ?></span></td><td><span class="status-pill <?= $p['active']?'active':'cancelled' ?>"><?= $p['active']?'Ativo':'Oculto' ?></span></td><td><div class="actions"><a class="button secondary compact" href="<?= Security::e(app_url('?route=products&edit='.(int)$p['id'])) ?>">Editar</a><a class="button secondary compact" href="<?= Security::e(app_url('?route=product-config&id='.(int)$p['id'])) ?>">Ficha técnica / adicionais</a><?php if($p['track_stock']&&Auth::can('inventory.manage')):?><a class="button secondary compact" href="<?= Security::e(app_url('?route=inventory&product_id='.(int)$p['id'])) ?>">Estoque</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<details class="technical-details"<?= $showEditor?' open':'' ?> style="margin-top:14px"><summary><?= $edit?'Editar produto selecionado':'Cadastrar novo produto' ?></summary><section class="card"><div class="section-head"><div><span class="eyebrow"><?= $edit?'EDIÇÃO':'NOVO PRODUTO' ?></span><h2><?= $edit?'Editar '.Security::e($edit['name']):'Adicionar produto' ?></h2></div><?php if($edit):?><a class="button secondary compact" href="<?= Security::e(app_url('?route=products')) ?>">Cancelar</a><?php endif;?></div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="product-save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label class="span-2">Nome do produto<input name="name" required value="<?= Security::e($edit['name']??'') ?>" placeholder="Ex.: X-Bacon Especial"></label><label>Preço de venda<input name="price" required inputmode="decimal" value="<?= $edit?Security::e(number_format(((int)$edit['price_cents'])/100,2,',','')):'' ?>" placeholder="24,90"></label><label>SKU<input name="sku" value="<?= Security::e($edit['sku']??'') ?>" placeholder="Opcional"></label><label class="span-2">Categoria<select name="category_id"><option value="0">Outros / sem categoria</option><?php foreach($categories as$c):?><option value="<?= (int)$c['id'] ?>"<?= em_selected($edit['category_id']??0,$c['id']) ?>><?= Security::e($c['name']) ?><?= !$c['active']?' (inativa)':'' ?></option><?php endforeach;?></select></label><label>Unidade de estoque<input name="stock_unit" value="<?= Security::e($edit['stock_unit']??'un') ?>" placeholder="un, kg, L"></label><label>Estoque mínimo<input name="min_stock_qty" inputmode="decimal" value="<?= Security::e((string)($edit['unit_min_stock']??$edit['min_stock_qty']??0)) ?>"></label><label>Unidade de compra<input name="purchase_unit" value="<?= Security::e($edit['purchase_unit']??'un') ?>" placeholder="caixa, fardo, kg"></label><label>Fator de compra<input name="purchase_factor" inputmode="decimal" value="<?= Security::e((string)($edit['purchase_factor']??1)) ?>"><small>Ex.: 1 caixa = 24 unidades → fator 24.</small></label><?php if($edit):?><label>Saldo disponível<?= $currentUnit?' · '.Security::e($currentUnit['name']):'' ?><input value="<?= Security::e((string)($edit['unit_stock_qty']??0).' '.($edit['stock_unit']??'un')) ?>" readonly></label><label>Reservado<input value="<?= Security::e((string)($edit['reserved_qty']??0).' '.($edit['stock_unit']??'un')) ?>" readonly></label><?php else:?><label>Estoque inicial<?= $currentUnit?' · '.Security::e($currentUnit['name']):'' ?><input name="stock_qty" inputmode="decimal" value="0"></label><div class="muted">O estoque inicial entra somente na unidade selecionada. Depois, use Estoque ou Compras.</div><?php endif;?><label class="checkbox span-2"><input type="checkbox" name="track_stock"<?= em_checked($edit['track_stock']??0) ?>> Controlar disponibilidade pelo estoque</label><label class="span-2">Foto do produto (URL HTTPS)<input type="url" name="image_url" value="<?= Security::e($edit['image_url']??'') ?>" placeholder="https://..."><small>Use somente HTTPS. Fotos HTTP são bloqueadas pelo Android e não serão aceitas em novos cadastros.</small></label><label class="span-2">Descrição<textarea name="description"><?= Security::e($edit['description']??'') ?></textarea></label><label class="checkbox span-2"><input type="checkbox" name="active"<?= em_checked($edit?($edit['active']??0):1) ?>> Publicado no cardápio</label><button class="primary span-2"><?= $edit?'Salvar alterações':'Publicar produto' ?></button></form></section></details>
<details class="technical-details" style="margin-top:12px"><summary>Gerenciar categorias</summary><section class="card"><div class="section-head"><div><span class="eyebrow">ORGANIZAÇÃO</span><h2>Categorias</h2></div></div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="category-save"><label>Nome<input name="name" required placeholder="Ex.: Hambúrgueres"></label><label>Ordem de exibição<input type="number" name="sort_order" value="0"></label><button class="secondary span-2">Criar categoria</button></form><div class="table-wrap" style="margin-top:14px"><table class="table"><thead><tr><th>Categoria</th><th>Ordem</th><th>Status</th></tr></thead><tbody><?php foreach($categories as$c):?><tr><td><?= Security::e($c['name']) ?></td><td><?= (int)$c['sort_order'] ?></td><td><span class="status-pill <?= $c['active']?'active':'cancelled' ?>"><?= $c['active']?'Ativa':'Inativa' ?></span></td></tr><?php endforeach;?></tbody></table></div></section></details>
<script>const ps=document.getElementById('product-search'),cf=document.getElementById('category-filter'),sf=document.getElementById('status-filter');function filterProducts(){const q=(ps?.value||'').trim().toLocaleLowerCase('pt-BR'),cat=cf?.value||'',st=sf?.value||'';document.querySelectorAll('[data-product-row]').forEach(row=>{row.hidden=(q&&!row.dataset.search.includes(q))||(cat&&row.dataset.category!==cat)||(st&&row.dataset.status!==st)})}ps?.addEventListener('input',filterProducts);cf?.addEventListener('change',filterProducts);sf?.addEventListener('change',filterProducts);</script>
<?php em_footer();
